import {GOGETA_BLUE_META as META} from './gogeta-blue-meta.js';
import {gogetaBluePose} from '../characters/gogeta_blue.js';
import {personalCaster} from '../engine/personal-ultimate.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
export function gogetaBlueSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const m=META[key],im=images[key];if(!m||!im?.complete||!im.naturalWidth)return;row=Math.max(0,Math.min(m.rows-1,row));col=Math.max(0,Math.min(m.rowCounts[row]-1,col));const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,col*w,row*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawGogetaBlueActor(ctx,images,d,f,hurt=false,override=null){let p=gogetaBluePose(f,hurt),y=f.y;
 if(f.introAge!=null){const n=Math.min(7,Math.floor(f.introAge/2.5*8));p={key:'gogeta_blue_intro',row:Math.floor(n/4),frame:n%4};y-=Math.max(0,1-f.introAge/.6)*70;}
 else if(personalCaster(d,f)||override){const c=d.personalUltimate?.cinematic||d.teamUltimate?.cinematic;p={key:'gogeta_blue_ultimate_actor',row:0,frame:c?Math.min(3,Math.floor(c.elapsed/cinematicSteps(c)*4)):3};}
 if(f.state==='defeat')p={key:'gogeta_blue',row:7,frame:Math.min(3,Math.floor((d.tick-(f.deathTick??d.tick))/7))};
 gogetaBlueSprite(ctx,images,p.key,p.row,p.frame,f.x,y,.86,0,f.face);
}
export function drawGogetaBlueBack(ctx,images,d,clock=0){for(const f of d.fighters)if(f.id==='gogeta_blue'&&f.hp>0&&f.introAge!=null&&f.introAge>.65){const age=f.introAge;ctx.save();ctx.globalAlpha=age<1.25?.5:.7;gogetaBlueSprite(ctx,images,'gogeta_blue_intro_vfx',0,age<1.25?Math.min(1,Math.floor((age-.65)*3)):2+Math.floor(clock*8)%2,f.x,f.y-(age<1.25?0:48),age<1.25?.5:.7);ctx.restore();}}
function beamWarning(ctx,a){ctx.save();ctx.translate(a.x,a.y);ctx.rotate(Math.atan2(a.dy,a.dx));ctx.fillStyle='#38cfff18';ctx.fillRect(0,-65,1255,130);ctx.strokeStyle='#7eeaff';ctx.lineWidth=2;ctx.setLineDash([12,7]);ctx.strokeRect(0,-65,1255,130);ctx.restore();}
export function drawGogetaBlueWorld(ctx,images,d,clock=0){const a=d.personalUltimate?.attack;if(a?.kind==='fullforce'&&a.phase==='warning')beamWarning(ctx,a);}
export function drawGogetaBlueShot(ctx,images,s,x,y,clock){const angle=Math.atan2(s.vy,s.vx);if(s.kind==='fullforce'){
 const m=META.gogeta_blue_ultimate_vfx,im=images.gogeta_blue_ultimate_vfx;if(!im?.complete||!im.naturalWidth)return;const frame=2+Math.floor(clock*10)%2,b=m.bounds[0][frame],[w,h]=m.frameSize,fromX=s.fromX??x,fromY=s.fromY??y+28,length=Math.max(30,Math.hypot(s.x-fromX,s.y-fromY));
 ctx.save();ctx.translate(fromX,fromY-65);ctx.rotate(angle);ctx.scale(length/(b[2]-b[0]),130/(b[3]-b[1]));ctx.drawImage(im,frame*w,0,w,h,-b[0],-(b[1]+b[3])/2,w,h);ctx.restore();
 }else gogetaBlueSprite(ctx,images,'gogeta_blue_vfx',s.kind==='godpunisher'?1:0,Math.floor(clock*10)%2,x,y-37,s.kind==='godpunisher'?.25:.28,angle);}
export function drawGogetaBlueBurst(ctx,images,b){const p=1-b.life/b.max;if(b.action==='fullforce'){gogetaBlueSprite(ctx,images,'gogeta_blue_ultimate_vfx',1,Math.min(3,Math.floor(p*4)),b.x,b.y,.8);return;}const row=b.action==='stardustbreaker'?0:b.action==='godpunisher'?1:2;gogetaBlueSprite(ctx,images,'gogeta_blue_vfx',row,row===2?Math.min(3,Math.floor(p*4)):2+Math.min(1,Math.floor(p*2)),b.x,b.y,b.action==='stardustbreaker'?.65:.4);}
export function drawGogetaBlueChat(ctx,images,c,line='Full Force Kamehameha!'){const p=c.elapsed/cinematicSteps(c),row=p<.5?0:1,col=1,m=META.gogeta_blue_dialogue,b=m.bounds[row][col],w=b[2]-b[0],h=b[3]-b[1],scale=Math.min(780/w,180/h),cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));gogetaBlueSprite(ctx,images,'gogeta_blue_dialogue',row,col,480-(cx-m.pivot[0])*scale,438-(cy-m.pivot[1])*scale,scale);const x=480+w*scale*.15;ctx.fillStyle='#d9faff';ctx.textAlign='center';ctx.font='bold 14px Georgia';ctx.fillText('GOGETA BLUE',x,450,w*scale*.54);ctx.font='bold 19px Georgia';ctx.fillText(line,x,476,w*scale*.54);ctx.restore();}
export function drawGogetaBlueCinematic(ctx,images,d){const c=d.personalUltimate?.cinematic;if(c?.kind==='fullforce')drawGogetaBlueChat(ctx,images,c);}
export function drawGogetaBlueTeamWorld(ctx,images,d,clock=0){const a=d.teamUltimate?.attack;if(!a)return;const dx=a.targetX-a.x,dy=a.targetY-a.y,n=Math.hypot(dx,dy)||1;if(a.phase==='warning'){ctx.save();ctx.strokeStyle='#63ddff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(a.targetX,a.targetY,160,0,Math.PI*2);ctx.stroke();ctx.restore();}else if(a.phase==='travel'){const p=Math.max(0,Math.min(1,(d.tick-a.launch)/(a.impact-a.launch)));drawGogetaBlueShot(ctx,images,{kind:'fullforce',vx:dx/n,vy:dy/n,x:a.x+dx*p,y:a.y+dy*p,fromX:a.x,fromY:a.y},a.x+dx*p,a.y+dy*p-28,clock);}else gogetaBlueSprite(ctx,images,'gogeta_blue_ultimate_vfx',1,Math.min(3,Math.floor((d.tick-a.impact)/12)),a.targetX,a.targetY-28,1);}
